mapper.select:
SELECT id, event_id, change_kind, payload, status, retry_count, max_retry, next_retry_at, last_error, locked_by, locked_at, processed_at, source_module, source_biz_id, created_at, updated_at, version FROM sys_authorization_invalidation_outbox WHERE status IN
#{status}
AND (next_retry_at IS NULL OR next_retry_at <= #{now}) ORDER BY created_at ASC LIMIT #{limit}

mapper.delete:
DELETE
FROM sys_authorization_invalidation_outbox
WHERE status = 'SUCCESS'
  AND processed_at IS NOT NULL
  AND processed_at < #{cutoffTime}
LIMIT #{batchSize}
